    inline entry const sDocs[] =
    {
        { "", "Utilities to support packages." },
        { "ModuleInfo", "A namedtuple with minimal info about a module." },
        { "ModuleInfo.__new__", "Create new instance of ModuleInfo(module_finder, name, ispkg)" },
        { "ModuleInfo._make", "Make a new ModuleInfo object from a sequence or iterable" },
        { "ModuleInfo.__replace__", "Return a new ModuleInfo object replacing specified fields with new values" },
        { "ModuleInfo._replace", "Return a new ModuleInfo object replacing specified fields with new values" },
        { "ModuleInfo.__repr__", "Return a nicely formatted representation string" },
        { "ModuleInfo._asdict", "Return a new dict which maps field names to their values." },
        { "ModuleInfo.__getnewargs__", "Return self as a plain tuple.  Used by copy and pickle." },
        { "extend_path", "Extend a package's path.\n\nIntended use is to place the following code in a package's __init__.py:\n\n    from pkgutil import extend_path\n    __path__ = extend_path(__path__, __name__)\n\nFor each directory on sys.path that has a subdirectory that\nmatches the package name, add the subdirectory to the package's\n__path__.  This is useful if one wants to distribute different\nparts of a single logical package as multiple directories.\n\nIt also looks for *.pkg files beginning where * matches the name\nargument.  This feature is similar to *.pth files (see site.py),\nexcept that it doesn't special-case lines starting with 'import'.\nA *.pkg file is trusted at face value: apart from checking for\nduplicates, all entries found in a *.pkg file are added to the\npath, regardless of whether they are exist the filesystem.  (This\nis a feature.)\n\nIf the input path is not a list (as is the case for frozen\npackages) it is returned unchanged.  The input path is not\nmodified; an extended copy is returned.  Items are only appended\nto the copy at the end.\n\nIt is assumed that sys.path is a sequence.  Items of sys.path that\nare not (unicode or 8-bit) strings referring to existing\ndirectories are ignored.  Unicode items of sys.path that cause\nerrors when used as filenames may cause this function to raise an\nexception (in line with os.path.isdir() behavior).\n" },
        { "find_loader", "Find a \"loader\" object for fullname\n\nThis is a backwards compatibility wrapper around\nimportlib.util.find_spec that converts most failures to ImportError\nand only returns the loader rather than the full spec\n" },
        { "get_data", "Get a resource from a package.\n\nThis is a wrapper round the PEP 302 loader get_data API. The package\nargument should be the name of a package, in standard module format\n(foo.bar). The resource argument should be in the form of a relative\nfilename, using '/' as the path separator. The parent directory name '..'\nis not allowed, and nor is a rooted name (starting with a '/').\n\nThe function returns a binary string, which is the contents of the\nspecified resource.\n\nFor packages located in the filesystem, which have already been imported,\nthis is the rough equivalent of\n\n    d = os.path.dirname(sys.modules[package].__file__)\n    data = open(os.path.join(d, resource), 'rb').read()\n\nIf the package cannot be located or loaded, or it uses a PEP 302 loader\nwhich does not support get_data(), then None is returned.\n" },
        { "get_importer", "Retrieve a finder for the given path item\n\nThe returned finder is cached in sys.path_importer_cache\nif it was newly created by a path hook.\n\nThe cache (or part of it) can be cleared manually if a\nrescan of sys.path_hooks is necessary.\n" },
        { "get_loader", "Get a \"loader\" object for module_or_name\n\nReturns None if the module cannot be found or imported.\nIf the named module is not already imported, its containing package\n(if any) is imported, in order to establish the package __path__.\n" },
        { "iter_importers", "Yield finders for the given module name\n\nIf fullname contains a '.', the finders will be for the package\ncontaining fullname, otherwise they will be all registered top level\nfinders (i.e. those on both sys.meta_path and sys.path_hooks).\n\nIf the named module is in a package, that package is imported as a side\neffect of invoking this function.\n\nIf no module name is specified, all top level finders are produced.\n" },
        { "iter_modules", "Yields ModuleInfo for all submodules on path,\nor, if path is None, all top-level modules on sys.path.\n\n'path' should be either None or a list of paths to look for\nmodules in.\n\n'prefix' is a string to output on the front of every module name\non output.\n" },
        { "resolve_name", "\nResolve a name to an object.\n\nIt is expected that `name` will be a string in one of the following\nformats, where W is shorthand for a valid Python identifier and dot stands\nfor a literal period in these pseudo-regexes:\n\nW(.W)*\nW(.W)*:(W(.W)*)?\n\nThe first form is intended for backward compatibility only. It assumes that\nsome part of the dotted name is a package, and the rest is an object\nsomewhere within that package, possibly nested inside other objects.\nBecause the place where the package stops and the object hierarchy starts\ncan't be inferred by inspection, repeated attempts to import must be done\nwith this form.\n\nIn the second form, the caller makes the division point clear through the\nprovision of a single colon: the dotted name to the left of the colon is a\npackage to be imported, and the dotted name to the right is the object\nhierarchy within that package. Only one import is needed in this form. If\nit ends with the colon, then a module object is returned.\n\nThe function will return an object (which might be a module), or raise one\nof the following exceptions:\n\nValueError - if `name` isn't in a recognised format\nImportError - if an import failed when it shouldn't have\nAttributeError - if a failure occurred when traversing the object hierarchy\n                 within the imported package to get to the desired object.\n" },
        { "walk_packages", "Yields ModuleInfo for all modules recursively\non path, or, if path is None, all accessible modules.\n\n'path' should be either None or a list of paths to look for\nmodules in.\n\n'prefix' is a string to output on the front of every module name\non output.\n\nNote that this function must import all *packages* (NOT all\nmodules!) on the given path, in order to access the __path__\nattribute to find submodules.\n\n'onerror' is a function which gets called with one argument (the\nname of the package which was being imported) if any exception\noccurs while trying to import a package.  If no onerror function is\nsupplied, ImportErrors are caught and ignored, while all other\nexceptions are propagated, terminating the search.\n\nExamples:\n\n# list all modules python can access\nwalk_packages()\n\n# list all submodules of ctypes\nwalk_packages(ctypes.__path__, ctypes.__name__+'.')\n" },
    };
